def render(template):
    pieces = []
    for part in template:
        if isinstance(part, str):
            pieces.append(part)
            continue
        value = part.value
        if part.conversion == "r":
            value = repr(value)
        elif part.conversion == "s":
            value = str(value)
        elif part.conversion == "a":
            value = ascii(value)
        pieces.append(format(value, part.format_spec))
    return "".join(pieces)

