def parameterize(template):
    sql = []
    parameters = []
    for part in template:
        if isinstance(part, str):
            sql.append(part)
        else:
            parameters.append(part.value)
            sql.append(f"${len(parameters)}")
    return "".join(sql), tuple(parameters)

